def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    last_m = my[-1]
    last_o = op[-1]

    opp_c = op.count('C')
    opp_d = n - opp_c
    my_d = n - my.count('C')

    opp_c_run = 0
    for x in reversed(op):
        if x == 'C':
            opp_c_run += 1
        else:
            break

    opp_d_run = 0
    if last_o == 'D':
        for x in reversed(op):
            if x == 'D':
                opp_d_run += 1
            else:
                break

    if n >= 5:
        r5 = op[-5:]
    else:
        r5 = op
    if n >= 10:
        r10 = op[-10:]
    else:
        r10 = op

    r5d = r5.count('D')
    r10d = r10.count('D')

    exploit = False
    last_completed_d = -1
    for i in range(n - 2, -1, -1):
        if my[i] == 'D':
            last_completed_d = i
            break

    if last_completed_d >= 0 and op[last_completed_d + 1] == 'C':
        clean = True
        for j in range(last_completed_d + 2, n):
            if op[j] == 'D':
                clean = False
                break
        if clean:
            exploit = True

    if exploit:
        return 'D'

    if last_m == 'C' and last_o == 'C':
        if my_d == 0 and opp_c_run >= 20:
            return 'D'
        if opp_c_run >= 30 and rng.random() < 0.03:
            return 'D'

    if last_o == 'D':
        if last_m == 'D':
            if opp_c == 0:
                return 'D'
            if opp_c >= 2 * opp_d:
                return 'C'
            return 'D'

        if n >= 2 and my[-2] == 'D' and opp_c >= 2 * opp_d:
            return 'C'
        if opp_d_run <= 1 and opp_c >= 3 * opp_d and r10d <= 1:
            return 'C'
        return 'D'

    if last_m == 'D':
        if opp_d > opp_c or r5d >= 3:
            return 'D'
        return 'C'

    if r5d >= 2 or r10d >= 4 or opp_d > opp_c:
        return 'D'
    return 'C'
